INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Faithlife Study Bible', 'Jeremias', 49, 18, 'Sodom and Gomorrah and their neighbors Places destroyed by Yahweh for wickedness (Gen 19). The traditional location of Sodom and Gomorrah is either within or very close to Edomite territory. See note on Isa 1:9.');
INSERT INTO commentaries (author, book, chapter, verse, text) VALUES ('Faithlife Study Bible', 'Jeremias', 49, 19, 'like a lion The imagery in Jer 49:19–22 is repeated for Babylon in 50:44–46.');
